// Opportunity cards server: runs as an isolated instance with its own storage.
// Verdicts are recorded here, never written back to the sheet by the app
// itself; publishing stays a human decision in the workspace.
export class App {
	constructor(ctx, env) {
		this.ctx = ctx;
		this.env = env;
	}

	async fetch(request) {
		const url = new URL(request.url);
		if (url.pathname === "/verdicts") {
			const verdicts = (await this.ctx.storage.kv.get("verdicts")) ?? {};
			if (request.method === "POST") {
				const body = await request.json();
				verdicts[String(body.number)] = { value: body.value, at: Date.now() };
				await this.ctx.storage.kv.put("verdicts", verdicts);
			}
			return Response.json(verdicts);
		}
		return new Response("not found", { status: 404 });
	}
}

