// Opportunity cards: one card per row of the granted "opportunities" sheet.
// Every tenant choice (which sheet, which columns, who reviews) comes from
// the manifest through tedix.call("context"); nothing here names a tenant.
const root = document.getElementById("app");
const state = { cards: [], index: 0, verdicts: new Map(), context: null };

const text = (tag, content, cls) => {
	const node = document.createElement(tag);
	if (cls) node.className = cls;
	node.textContent = content ?? "";
	return node;
};

function columnIndex(columns, wanted) {
	const needle = String(wanted ?? "").toLowerCase();
	return columns.findIndex((column) => String(column).toLowerCase().startsWith(needle));
}

function cardsFromSheet(sheet, settings) {
	const columns = settings.columns ?? {};
	const at = (row, key, fallback) => {
		const index = columnIndex(sheet.columns, columns[key] ?? fallback);
		return index >= 0 ? row[index] : null;
	};
	return sheet.rows.map((row, number) => ({
		number: at(row, "number", "#") ?? number + 1,
		source: at(row, "source", "Source"),
		who: at(row, "who", "Who"),
		why: at(row, "why", "Why"),
		draft: at(row, "draft", "Draft"),
		useful: at(row, "useful", "Useful?"),
	}));
}

function render() {
	root.replaceChildren();
	const style = document.createElement("style");
	style.textContent = `
		.card{border:1px solid color-mix(in srgb,CanvasText 18%,transparent);border-radius:12px;padding:16px;display:grid;gap:10px;max-width:720px}
		.meta{display:flex;justify-content:space-between;gap:12px;font-size:12px;opacity:.75}
		.why{font-size:15px;font-weight:600}
		.draft{white-space:pre-wrap;background:color-mix(in srgb,CanvasText 6%,transparent);border-radius:8px;padding:10px;font-size:13px}
		.row{display:flex;flex-wrap:wrap;gap:8px}
		button{border:1px solid color-mix(in srgb,CanvasText 25%,transparent);background:transparent;color:inherit;border-radius:999px;padding:8px 14px;cursor:pointer;min-height:40px}
		button[data-primary]{background:CanvasText;color:Canvas;border-color:CanvasText}
		.done{opacity:.7}
		a{color:inherit}
	`;
	root.append(style);
	const { context, cards } = state;
	const reviewer = context?.settings?.reviewer ?? "you";
	const heading = text("h2", `${cards.length} opportunities for ${reviewer}`);
	heading.style.cssText = "margin:0 0 12px;font-size:16px";
	root.append(heading);
	if (cards.length === 0) {
		root.append(text("p", "No cards in the sheet yet."));
		return;
	}
	const card = cards[state.index % cards.length];
	const box = document.createElement("section");
	box.className = "card";
	box.setAttribute("aria-label", `Card ${card.number}`);
	const meta = document.createElement("div");
	meta.className = "meta";
	meta.append(text("span", `#${card.number} · ${card.who ?? ""}`));
	meta.append(text("span", `${state.index + 1} of ${cards.length}`));
	box.append(meta);
	box.append(text("p", card.why, "why"));
	if (card.source) {
		const link = document.createElement("a");
		link.href = String(card.source);
		link.textContent = String(card.source);
		link.rel = "noreferrer";
		link.target = "_blank";
		box.append(link);
	}
	if (card.draft) box.append(text("div", card.draft, "draft"));
	const verdict = state.verdicts.get(card.number) ?? card.useful;
	if (verdict) box.append(text("p", `Verdict: ${verdict}`, "done"));
	const row = document.createElement("div");
	row.className = "row";
	for (const [label, value, primary] of [
		["Useful", "yes", true],
		["Not useful", "no", false],
		["Skip", null, false],
	]) {
		const button = document.createElement("button");
		button.type = "button";
		button.textContent = label;
		if (primary) button.dataset.primary = "";
		button.addEventListener("click", () => {
			if (value) state.verdicts.set(card.number, value);
			state.index = (state.index + 1) % cards.length;
			render();
		});
		row.append(button);
	}
	box.append(row);
	const note = text(
		"p",
		`Role ${context?.role ?? "?"} · verdicts are kept by the app until its server runs in this workspace.`,
	);
	note.style.cssText = "font-size:12px;opacity:.7;margin:0";
	box.append(note);
	root.append(box);
}

async function start() {
	try {
		state.context = await tedix.call("context");
		const slot = state.context.settings?.slot ?? "opportunities";
		const sheet = await tedix.call("outputs.read", { slot });
		if (sheet?.kind !== "sheet") throw new Error("The granted slot is not a sheet");
		state.cards = cardsFromSheet(sheet, state.context.settings ?? {});
		render();
	} catch (error) {
		root.replaceChildren(text("p", `Cannot load cards: ${error.message ?? error}`));
	}
}

start();
